style:
/* 天青 —— 「个人简历」标头、天青实底标题条 */

.tw-tianqing.layout-band.resume-paper .paper-flow::before {
  content: "个 人 简 历";
  display: block;
  margin-bottom: 5mm;
  padding-bottom: 2.4mm;
  border-bottom: 0.9mm solid var(--paper-accent);
  color: #1f2a2e;
  font-family: var(--paper-font-family);
  font-size: calc(var(--paper-base-size) * 2.4);
  font-weight: 700;
  letter-spacing: 0.16em;
  print-color-adjust: exact;
}

.tw-tianqing.layout-band.resume-paper .paper-header::before {
  content: "PERSONAL RESUME";
  display: block;
  margin-bottom: 1.6mm;
  color: var(--paper-accent);
  font-size: calc(var(--paper-base-size) * 0.78);
  font-weight: 700;
  letter-spacing: 0.32em;
  flex: 0 0 100%;
  width: 100%;
}

.tw-tianqing.layout-band.resume-paper .paper-header {
  margin-bottom: 6.5mm;
  padding-bottom: 4mm;
  border-bottom: 0.25mm solid #dbe7ee;
  align-items: flex-start;
  flex-wrap: wrap;
  gap: 8mm;
}

.tw-tianqing.layout-band.resume-paper .paper-header__main {
  flex: 1 1 0;
  display: block;
  min-width: 0;
}

.tw-tianqing.layout-band.resume-paper .paper-photo {
  order: 3;
  width: 24mm;
  height: 32mm;
  border: 0.4mm solid #d7e4ec;
  border-radius: 0;
  box-shadow: none;
}

.tw-tianqing.layout-band.resume-paper .paper-photo--monogram {
  display: grid;
  place-items: center;
  background: #eef5f9;
  color: var(--paper-accent);
  font-size: calc(var(--paper-base-size) * 2);
  font-weight: 700;
}

.tw-tianqing.layout-band.resume-paper .paper-name {
  color: var(--paper-accent);
  font-family: var(--paper-font-family);
  font-size: calc(var(--paper-base-size) * 2.05);
  letter-spacing: 0.06em;
}

.tw-tianqing.layout-band.resume-paper .paper-identity {
  padding: 0;
  border: none;
  color: #5d7380;
  font-size: calc(var(--paper-base-size) * 0.84);
}

.tw-tianqing.layout-band.resume-paper .paper-role {
  margin-top: 1.4mm;
  color: #3d4b52;
  font-size: calc(var(--paper-base-size) * 0.92);
  font-weight: 400;
}

.tw-tianqing.layout-band.resume-paper .paper-contacts {
  display: flex;
  flex-wrap: wrap;
  gap: 1.4mm 6mm;
  margin-top: 3mm;
  padding-top: 0;
  border-top: none;
  color: #34434a;
  font-size: calc(var(--paper-base-size) * 0.86);
}

.tw-tianqing.layout-band.resume-paper .paper-contact {
  display: inline-flex;
  gap: 1.4mm;
}

.tw-tianqing.layout-band.resume-paper .paper-contact + .paper-contact::before {
  content: "";
  left: -3mm;
  width: 0.2mm;
  height: 3.2mm;
  background: #d5e2ea;
  print-color-adjust: exact;
}

.tw-tianqing.layout-band.resume-paper .paper-contact__label {
  color: #7b8b93;
}

/* 标题：整条天青底，白字带小图标 */
.tw-tianqing.layout-band.resume-paper .paper-style-block .paper-section__title {
  display: flex;
  align-items: center;
  gap: 2.4mm;
  margin-bottom: 3.2mm;
  padding: 1.2mm 3.2mm;
  background: var(--paper-accent);
  border-radius: 0;
  color: #fff;
  font-size: calc(var(--paper-base-size) * 1.04);
  letter-spacing: 0.1em;
  print-color-adjust: exact;
}

.tw-tianqing.layout-band.resume-paper .paper-style-block .paper-section__icon {
  display: grid;
  flex: 0 0 auto;
  place-items: center;
  width: 4mm;
  height: 4mm;
  color: #fff;
}

.tw-tianqing.layout-band.resume-paper .paper-style-block .paper-section__icon svg {
  width: 100%;
  height: 100%;
}

.tw-tianqing.layout-band.resume-paper .paper-section__body {
  color: #2f3d44;
}

.tw-tianqing.layout-band.resume-paper .paper-item-title {
  color: #1e2a30;
  font-size: calc(var(--paper-base-size) * 1.02);
}

.tw-tianqing.layout-band.resume-paper .paper-item-period {
  color: #7c8d96;
  font-size: calc(var(--paper-base-size) * 0.86);
}

.tw-tianqing.layout-band.resume-paper .paper-item-sub {
  color: #44535b;
}

.tw-tianqing.layout-band.resume-paper .paper-rich ul,
.tw-tianqing.layout-band.resume-paper .paper-rich ol {
  padding-left: 1.1em;
}

.tw-tianqing.layout-band.resume-paper .paper-rich li::marker {
  color: var(--paper-accent);
}

/* 技能：三列进度条 */
.tw-tianqing.layout-band.resume-paper .paper-skills {
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 2mm 7mm;
}

.tw-tianqing.layout-band.resume-paper .paper-skill {
  display: block;
  padding-bottom: 0;
  border-bottom: none;
}

.tw-tianqing.layout-band.resume-paper .paper-skill__name {
  display: block;
  font-size: calc(var(--paper-base-size) * 0.9);
  font-weight: 400;
}

.tw-tianqing.layout-band.resume-paper .paper-skill__dots {
  display: flex;
  gap: 0;
  margin-top: 1.2mm;
}

.tw-tianqing.layout-band.resume-paper .paper-skill__dots i {
  width: 100%;
  height: 1.8mm;
  border-radius: 0;
  background: #e3edf3;
}

.tw-tianqing.layout-band.resume-paper .paper-skill__dots i.filled {
  background: var(--paper-accent);
}

.tw-tianqing.layout-band.resume-paper .paper-skill__level {
  display: block;
  margin-top: 1mm;
  color: #75868f;
  font-size: calc(var(--paper-base-size) * 0.8);
}

.tw-tianqing.layout-band.resume-paper .paper-note__tag {
  color: var(--paper-accent);
  font-weight: 600;
}

.tw-tianqing.layout-band.resume-paper .paper-footer {
  border-top: 0.2mm solid #e1ebf1;
  color: #9dabb3;
}
